<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import ConfirmationModal from '@/Components/ConfirmationModal.vue'; import InputError from '@/Components/InputError.vue'; import ValidationSummary from '@/Components/ValidationSummary.vue'; import Button from '@/Components/UI/Button.vue'; import PageHeader from '@/Components/UI/PageHeader.vue'; import {Head,useForm,router} from '@inertiajs/vue3'; import {reactive, ref} from 'vue';
const props=defineProps<{packages:any[];filters:any}>(); const filters=reactive({...props.filters}); const apply=()=>router.get(route('admin.packages.index'),filters,{preserveState:true,replace:true}); const reset=()=>{filters.search='';filters.active='';apply()}; const form=useForm({name:'',minimum_guests:1,maximum_guests:50,price:'',is_active:true}); const pendingPackage=ref<any>(null); const toggle=(item:any)=>{if(!item.is_active){pendingPackage.value=item;return;} updatePackage(item);}; const updatePackage=(item:any)=>router.put(route('admin.packages.update',item.id),{...item,is_active:!item.is_active},{onFinish:()=>pendingPackage.value=null});
</script>
<template><Head title="Packages"/><AuthenticatedLayout><template #header><PageHeader title="Packages" /></template><div class="fe-page fe-page-standard space-y-5"><form @submit.prevent="form.post(route('admin.packages.store'))" class="fe-card grid gap-3 p-4 sm:grid-cols-5"><div><input v-model="form.name" placeholder="Name" required class="w-full"><InputError :message="form.errors.name" class="mt-1"/></div><div><input v-model="form.minimum_guests" type="number" class="w-full"><InputError :message="form.errors.minimum_guests" class="mt-1"/></div><div><input v-model="form.maximum_guests" type="number" class="w-full"><InputError :message="form.errors.maximum_guests" class="mt-1"/></div><div><input v-model="form.price" type="number" placeholder="Price" class="w-full"><InputError :message="form.errors.price" class="mt-1"/></div><Button type="submit">Add package</Button><div class="sm:col-span-5"><ValidationSummary :errors="form.errors"/></div></form><form @submit.prevent="apply" class="fe-card fe-card-muted flex flex-wrap gap-2 p-3"><input v-model="filters.search" placeholder="Search package name" class="w-full min-w-0 sm:w-auto sm:min-w-56"><select v-model="filters.active" class="w-full min-w-0 sm:w-auto"><option value="">All packages</option><option value="active">Active</option><option value="inactive">Inactive</option></select><Button type="submit">Search</Button><Button type="button" variant="ghost" @click="reset">Reset</Button></form><div class="fe-card overflow-hidden"><div v-for="packageItem in packages" :key="packageItem.id" class="flex flex-wrap items-start justify-between gap-3 border-b border-[color:var(--fe-border)] p-4"><span class="min-w-0 break-words"><b>{{packageItem.name}}</b> — Guest range: {{packageItem.minimum_guests}}–{{packageItem.maximum_guests}} — Price: <template v-if="packageItem.price !== null">${{packageItem.price}}</template><template v-else>Price not set</template> — {{packageItem.is_active?'Active':'Inactive'}}</span><Button type="button" variant="ghost" class="shrink-0" @click="toggle(packageItem)">{{packageItem.is_active?'Deactivate':'Activate'}}</Button></div><p v-if="!packages.length" class="p-4 text-[color:var(--fe-text-secondary)]">No packages match your search or filter.</p></div></div><ConfirmationModal :show="!!pendingPackage" title="Deactivate package?" message="This package will no longer be available for new event assignments." confirm-label="Deactivate package" @close="pendingPackage=null" @confirm="updatePackage(pendingPackage)"/></AuthenticatedLayout></template>
